std::vector<int> src = {1, 2};
std::vector<int> dest = {3, 4};

// Efficiently append elements using back_inserter
std::copy(src.begin(), src.end(),
          std::back_inserter(dest));
// dest -> {3, 4, 1, 2}

// Requires push_front capability (e.g., std::list or std::deque)
std::list<int> L1 = {100};
std::vector<int> V2 = {1, 2, 3};

// Prepend elements in reverse order of iteration
std::copy(V2.begin(), V2.end(),
          std::front_inserter(L1));
// L1 -> {3, 2, 1, 100}

std::vector<int> V = {1, 5};
std::list<int> L = {2, 3, 4};

// Insert L starting at the second position of V (V.begin() + 1)
std::copy(L.begin(), L.end(),
          std::inserter(V, V.begin() + 1));
// V -> {1, 2, 3, 4, 5}
